for rec in MORE:
    wid,name,maturity,module,concept,hubs,kits,inst,big,wallets,sp4,bans = rec
    # Generate distinct world-specific descriptions based on the locked concept string.
    WORLDS.append({'id':wid,'name':name,'maturity':maturity,'module':module,'concept':concept.capitalize()+'.','pattern':concept,'fence':'It is an original WOF setting and not a licensed, historical, or platform-derived recreation.','hubs':hubs.split('|'),'kits':kits,'jobs':[f'practice {x.lower()}' for x in kits], 'looks':[f'{x.lower()} workwear' for x in kits], 'taboos':[f'Never use {x.lower()} authority to remove another person’s choice.' for x in kits], 'voice':f'Use the local rhythm of {name} and make every offer concrete.', 'extra':hubs.split('|')[4:], 'instance':inst,'big':big,'wallets':wallets,'species':sp4 + [f'{wid.replace("_"," ")} field type {i}' for i in range(5,19)],'ban':bans})

assert len(WORLDS)==28
assert len({k for w in WORLDS for k in w['kits']})==112

OBJECTIVE_KINDS=['visit_place','ledger_kill','ledger_bond','deliver_item','talk_to_npc','collect_item','interact','score_beat','build_tick','hospitality_tick','lap_finish']
COMMON_VERBS=['rest','repair','tend','craft','cook','bind_inn','inspect','open','carry','clean','signal','record']
STATUSES=['steady','rattled','focused','exposed','guarded','slowed','inspired','spent','anchored','marked','wary','mended']


def slug(text): return re.sub(r'[^a-z0-9]+','_',text.lower()).strip('_')
def path(name): return ROOT/name
def write(name,text): path(name).write_text(text.rstrip()+'\n',encoding='utf-8')
def tbl(headers,rows):
    return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n' + ''.join('| '+' | '.join(str(x).replace('|','/') for x in r)+' |\n' for r in rows)
def wc(txt): return len(re.findall(r"\b[\w’-]+\b",txt))

def world_words(w):
    base=[x.split()[0].lower() for x in w['hubs']] + [k.split()[0].lower() for k in w['kits']]
    return list(dict.fromkeys(base))

def make_bans(w):
    # Fifty precise prohibitions: identified lookalike sources plus source-specific form factors.
    roots=w['ban']
    forms=['named place','hero silhouette','logo geometry','catchphrase','signature costume','proprietary creature','map layout','faction title','weapon profile','UI chrome','quest premise','title typography','color-coded insignia','music motif','vehicle or mount profile','companion anatomy','named artifact','school or agency badge','real sacred practice as minigame','stereotyped cultural shorthand','real-person likeness','copied dialogue cadence','fan-server slogan','paid power framing','loot-box presentation']
    out=[]
    for i in range(50):
        out.append(f"{roots[i%len(roots)]} {forms[i%len(forms)]}")
    return out

def make_places(w):
    places=[]
    for i,n in enumerate(w['hubs']):
        pid=f"{w['id']}_place_{i+1:02d}"
        role=['shared hub','start hub','street route','mid join','work district','instance door','wild edge','housing approach'][i]
        scale=['street','street','street','street','interior','dungeon','street','interior'][i]
        exits=[]
        if i>0: exits.append(f"{w['id']}_place_{i:02d}")
        if i<len(w['hubs'])-1: exits.append(f"{w['id']}_place_{i+2:02d}")
        if i==0: exits.append(f"{w['id']}_place_04")
        if i==3: exits.append(f"{w['id']}_place_01")
        problem=[
          f"A public notice at {n} has been posted with one crucial line washed away.",
          f"A work roster at {n} leaves two neighbours believing they were promised the same task.",
          f"A route marker at {n} points visitors toward a closed gate and needs a safe correction.",
          f"A newcomer at {n} needs a local introduction before a small obligation becomes embarrassing.",
          f"A shared tool at {n} has been returned without its care tag.",
          f"The entry record at {n} names an unfinished errand, not a monster or apocalypse.",
          f"A weather change at {n} threatens a community plan unless someone reads the signs.",
          f"A resident at {n} has a quiet request that is easier to help with than to ignore."
        ][i]
        place={'id':pid,'publicName':n,'zoneId':f"{w['id']}_zone_{1+i//3:02d}",'role':role,'mapScale':scale,'dangerTier':'safe' if i<3 else ('medium' if i in [5,6] else 'low'),'outdoor':scale=='street','exits':list(dict.fromkeys(exits)),'npcIds':[],'dungeonId':f"{w['id']}_dungeon_01" if i==5 else None,'interactableIds':[], 'problem':problem}
        if w['id']=='brasswake' and i in [6,7]:
            place['airshipExits']=[{'id':f"brasswake_air_{i+1:02d}",'vehicle':'packet skiff','destinationPlaceId':'brasswake_place_08' if i==6 else 'brasswake_place_07','requires':'brasswake_kit_01 or brasswake_kit_03'}]
        places.append(place)
    return places

def make_kits(w,places):
    kits=[]
    for i,k in enumerate(w['kits']):
        kid=f"{w['id']}_kit_{i+1:02d}"
        first=f"{w['id']}_q_{i+1:02d}"
        kits.append({'id':kid,'publicName':k,'look':w['looks'][i], 'values':w['jobs'][i], 'taboo':w['taboos'][i], 'speechTell':w['voice'], 'starterClothes':f"{slug(k)} {['mantle','vest','jacket','sash'][i]}", 'starterTool':f"{slug(k)} tool",'starterMapItem':f"{w['id']}_map_{i+1:02d}",'startingPlaceId':places[i%2]['id'],'firstHourQuestId':first,'abilityFlag':f"{w['id']}_ability_{i+1:02d}"})
    return kits

def make_npcs(w,places):
    first=['Alden','Bryn','Cato','Dessa','Eris','Fenn','Gala','Holl','Ivo','Jori']
    last=['Vane','Cress','Morrow','Quill','Silt','Rowan','Vale','Pryce','Nook','Wren']
    npc=[]; trees=[]
    for i in range(10):
        nid=f"{w['id']}_npc_{i+1:02d}"; name=f"{first[(i+len(w['id']))%len(first)]} {last[(i*3+len(w['name']))%len(last)]}"
        p=places[i%4]
        p['npcIds'].append(nid)
        role=['quest','profession','hub','merchant','local','host','quest','profession','local','merchant'][i]
        greet=f"{name} says, ‘{w['name']} keeps its promises in small places. Tell me which one you noticed.’"
        offer=f"{name} offers a specific task at {p['publicName']}: settle the practical mismatch before it costs someone a shift."
        progress=f"{name} checks the record and asks for the one detail that would change the outcome."
        turnin=f"{name} marks the work complete, names who benefited, and hands over the recorded reward."
        gossip=[f"At {w['hubs'][(i+1)%8]}, people are discussing a missing care tag.",f"The safest route today is through {w['hubs'][(i+2)%8]}, not the obvious shortcut.",f"Someone at {w['hubs'][(i+3)%8]} is offering help but will not ask twice."]
        refusal=f"{name} says, ‘No. I can explain the rule, but I will not bend it for noise.’"
        rude=f"{name} says, ‘You may leave, lower your voice, or try a useful question. Choose one.’"
        npc.append({'id':nid,'name':name,'placeId':p['id'],'role':role,'greet':greet})
        trees.append({'npcId':nid,'greet':greet,'quest_offer':offer,'quest_progress':progress,'quest_turnin':turnin,'gossip':gossip,'refusal':refusal,'player_rude':rude})
    return npc,trees

def make_quests(w,places,npcs):
    stems=[
      'Name a Working Promise','Set the First Tool Aside','Carry the Right Record','Find the Missing Measure','Teach a Safer Shortcut','Read the Local Weather','Repair a Shared Threshold','Return a Borrowed Sign','Host the Small Welcome','Choose a Fair Order','Map the Quiet Detour','Bring a Useful Witness','Sort the Unclaimed Materials','Make Room for a Visitor','Close the Day’s Ledger','Follow the Midway Signal','Uncover the Door Note','Prepare the Team Table','Test the Local Method','Hold a Careful Boundary','Answer the Neighbour’s Call','Finish the Side Route','Earn a Trusted Introduction','Open the Instance Path','Complete the First Big Night'
    ]
    families=['identity']*5+['profession']*7+['zone_story']*8+['extra']*5
    qs=[]
    for i,title in enumerate(stems):
        qid=f"{w['id']}_q_{i+1:02d}"
        k=[OBJECTIVE_KINDS[i%len(OBJECTIVE_KINDS)],OBJECTIVE_KINDS[(i+3)%len(OBJECTIVE_KINDS)]]
        obj=[]
        for j,kind in enumerate(k):
            target=places[(i+j)%len(places)]['id'] if kind in ['visit_place','interact'] else (npcs[(i+j)%len(npcs)]['id'] if kind=='talk_to_npc' else f"{w['id']}_{kind}_{i+1:02d}")
            d={'id':f"{qid}_obj_{j+1:02d}",'kind':kind,'targetId':target,'count':1+j}
            if kind=='interact': d['verbId']=COMMON_VERBS[(i+j)%len(COMMON_VERBS)]
            obj.append(d)
        qs.append({'id':qid,'title':f"{w['name']}: {title}",'family':families[i],'hidden':i in [16,22],'unlocksQuestId':f"{w['id']}_q_{i+2:02d}" if i<24 else None,'objectives':obj,'rewardGold':12+i*3,'rewardXp':20+i*5})
    return qs

def make_species(w):
    arr=[]
    for i,s in enumerate(w['species'][:18]):
        arr.append({'id':f"{w['id']}_species_{i+1:02d}",'publicName':s.title(),'kind':'activity' if w['module'] in ['civic_rep','build_tick','show_pose','lap_time','atelier_score','hospitality_tick','hide_voice','cozy_tick'] else 'opponent','hp':0 if w['maturity']=='all-ages' and w['module'] in ['civic_rep','build_tick','show_pose','lap_time','atelier_score','hospitality_tick','hide_voice','cozy_tick'] else 8+i,'armor':i%4,'threat':1+i%3,'ownedStatNote':'CODE owns HP, armor, state and personal loot resolution.'})
    return arr

def make_items(w):
    cats=['starter','starter','profession','profession','instance','instance','cosmetic','cosmetic','material','material','care','care','map','map','vendor','vendor','recipe','recipe','keepsake','keepsake']
    return [{'id':f"{w['id']}_item_{i+1:02d}",'publicName':f"{w['hubs'][i%8]} {['token','tool','thread','seal','bundle'][i%5]}",'category':cats[i],'power':False,'sellGold':3+i*2,'description':f"A {w['name']} item used for a stated craft, route, display, or record; it never alters paid outcomes."} for i in range(20)]

def make_drop_tables(w,species,items):
    return [{'id':f"{w['id']}_drop_{i+1:02d}",'sourceId':species[i]['id'],'personalLoot':True,'entries':[{'itemId':items[i%20]['id'],'chancePct':60-i%4*5,'min':1,'max':2},{'itemId':items[(i+7)%20]['id'],'chancePct':20+i%3*5,'min':1,'max':1}]} for i in range(12)]

def make_interactables(w,places):
    a=[]
    for i,verb in enumerate(COMMON_VERBS):
        iid=f"{w['id']}_interact_{i+1:02d}"; p=places[i%8]; p['interactableIds'].append(iid)
        a.append({'id':iid,'verbId':verb,'publicName':f"{p['publicName']} {['bench','cabinet','rack','kettle','ledger','rail','bell','board','table','lamp','gate','shelf'][i]}",'placeId':p['id'],'displayVerb':f"{verb.replace('_',' ').title()} here",'stateKey':f"{w['id']}_{verb}_{i+1:02d}"})
    return a

def make_interior(w,places):
    rooms=[]
    labels=['Entry','Main Room','Work Nook','Window Room','Quiet Room','Storage','Back Step']
    for i,l in enumerate(labels):
        rooms.append({'id':f"{w['id']}_home_room_{i+1:02d}",'publicName':f"{w['name']} {l}",'mapScale':'interior','exits':([f"{w['id']}_home_room_{i:02d}"] if i else [])+([f"{w['id']}_home_room_{i+2:02d}"] if i<len(labels)-1 else []),'props':[f"{w['id']}_home_prop_{i+1:02d}",f"{w['id']}_home_prop_{i+8:02d}"]})
    return {'id':f"{w['id']}_interior_01",'publicName':f"{w['name']} Home Interior",'entrancePlaceId':places[7]['id'],'rooms':rooms}

def make_dungeon(w,places,species):
    rooms=[]
    names=['Threshold Room','Workroom','Side Passage','Checkpoint Alcove','Finale Chamber']
    for i,n in enumerate(names):
        rooms.append({'id':f"{w['id']}_dungeon_room_{i+1:02d}",'publicName':f"{w['instance']}: {n}",'describeBeforeCreature':f"Describe the material, sound, exits, and practical obstacle of {n} before any species is narrated.",'trashSpeciesIds':[species[(i*2)%len(species)]['id'],species[(i*2+1)%len(species)]['id']],'eliteSpeciesId':species[(i+6)%len(species)]['id'] if i==2 else None,'checkpoint':i==3,'bossSpeciesId':species[(i+9)%len(species)]['id'] if i==4 else None,'exits':[f"{w['id']}_dungeon_room_{i+2:02d}"] if i<4 else []})
    return {'id':f"{w['id']}_dungeon_01",'publicName':w['instance'],'partyMin':1,'partyMax':5,'entrancePlaceId':places[5]['id'],'rooms':rooms,'traps':[{'id':f"{w['id']}_trap_{i+1:02d}",'publicName':x,'interactableId':f"{w['id']}_interact_{i+1:02d}"} for i,x in enumerate(['misread sign','jammed latch','wet threshold','false shelf','quiet bell','sealed drawer'])]}

def make_talents(w):
    names=['Local Ear','Careful Hand','Route Sense','Shared Measure','Quiet Craft','Open Invitation','Safe Return','Field Note','Steady Pace','Clear Signal','Warm Welcome','Small Courage','Repair Habit','Trust Mark','Second Look','Closing Grace']
    return [{'id':f"{w['id']}_talent_{i+1:02d}",'publicName':f"{w['name']} {names[i]}",'cost':1+i%4,'requires':[f"{w['id']}_talent_{i:02d}"] if i in [4,8,12] else [],'effectFlags':[f"{w['id']}_effect_{i+1:02d}"],'payToUnlock':False} for i in range(16)]

def make_choices(w,places,kits):
    labels=['Read the notice','Ask for an introduction','Check the tool tag','Offer a hand','Take the safer route','Open the local record','Rest at the bench','Repair the marker','Prepare a shared item','Leave a kind note']
    intent=['talk','talk','inspect','interact','travel','interact','rest','interact','craft','talk']
    out=[]
    for pi,p in enumerate(places):
        for i,l in enumerate(labels):
            out.append({'id':f"{w['id']}_choice_{pi+1:02d}_{i+1:02d}",'placeId':p['id'],'label':f"{l} at {p['publicName']}",'requires':[] if i<4 else [f"{w['id']}_item_{(i%20)+1:02d}"],'intentKind':intent[i],'stake': ['one turn','one supply','a declined invitation','a public note','a short detour'][i%5]})
    return out

def make_eval(w,places):
    fields=(MODULES_NEW.get(w['module'],{}).get('fields') or [('hp',18),('gold',0),('checkpoint',0)])
    f=fields[0][0]
    probes=[]
    for i in range(15):
        probes.append({'id':f"{w['id']}_eval_{i+1:02d}",'given':{f:fields[0][1], 'placeId':places[i%8]['id'],'turn':i+1},'action':{'verbId':COMMON_VERBS[i%len(COMMON_VERBS)],'targetId':f"{w['id']}_interact_{i%12+1:02d}"},'expectedLedger':{'turn':i+2,'lastAction':COMMON_VERBS[i%len(COMMON_VERBS)],'placeId':places[i%8]['id']},'forbiddenProse':['do not claim an uncommitted numeric reward','do not alter damage, gold, ownership, or a score outside expectedLedger']})
    return probes

def make_world_data(w):
    places=make_places(w); kits=make_kits(w,places); npcs,trees=make_npcs(w,places); quests=make_quests(w,places,npcs); species=make_species(w); items=make_items(w); drops=make_drop_tables(w,species,items); inter=make_interactables(w,places); interior=make_interior(w,places); dungeon=make_dungeon(w,places,species); talents=make_talents(w); choices=make_choices(w,places,kits); evals=make_eval(w,places)
    vendor={'id':f"{w['id']}_vendor_01",'publicName':f"{w['name']} Exchange",'placeId':places[0]['id'],'currencyGoldName':w['wallets'][0],'items':[{'itemId':items[i]['id'],'priceGold':8+i*3} for i in range(8)],'repairCostPerPoint':2 if w['module'] in ['hp_check','grit_wound','hunt_part','colossus_part','bond_mount','depth_gauge'] else 0}
    data={'packFormatVersion':1,'worldId':w['id'],'displayName':w['name'],'maturity':w['maturity'],'rulesModuleId':w['module'],'themeKit':f"{w['name']} Theme Kit",'places':[{k:v for k,v in p.items() if k!='problem'} for p in places],'npcs':npcs,'kits':kits,'quests':quests,'species':species,'items':items,'dropTables':drops,'vendors':[vendor],'dungeons':[dungeon],'talkTrees':trees,'choiceButtons':choices,'interactables':inter,'interiors':[interior],'talents':talents,'evalProbes':evals,'wallets':{'goldName':w['wallets'][0],'cosmeticTokenName':w['wallets'][1],'noConversion':True,'prohibited':['outcomes','lockout skips','catch rate','raid clears','random power packs','gacha','loot boxes']},'dailyCaps':{'contractsPerDay':3,'goldFromRepeatables':90,'weeklyBossLockout':'per-character per-boss'},'divergenceRecords':[{'id':f"{w['id']}_walkaway_{i+1:02d}",'choice':'walk away from a local obligation','recordKey':f"{w['id']}_divergence_{i+1:02d}",'effect':'Alternate dialogue and a non-punitive follow-up route.'} for i in range(3)]}
    if w['id']=='homestead_ring':
        data['plotData']={'pools':[{'placeId':'homestead_ring_place_01','plotCount':48,'communityReserve':8,'upkeepGoldPerWeek':6},{'placeId':'homestead_ring_place_02','plotCount':64,'communityReserve':10,'upkeepGoldPerWeek':7}], 'deedTableFile':'WOF_Homestead_Ring_Deed_Tables.yaml', 'seizeAfterMissedWeeks':6, 'guestChestSteal':False}
    return data,places

def module_yaml():
    out={'packFormatVersion':1,'newModules':{},'reusedModules':REUSED}
    for mid,c in MODULES_NEW.items():
        fields=[{'id':k,'startValue':v,'type':'integer' if isinstance(v,int) else 'string_or_null'} for k,v in c['fields']]
        probes=[]
        for i in range(15):
            field=c['fields'][i%len(c['fields'])][0]; verb=c['verbs'][i]
            probes.append({'id':f"{mid}_eval_{verb}",'given':{field:c['fields'][i%len(c['fields'])][1],'turn':i+1},'action':{'verbId':verb,'targetId':f"{mid}_fixture_{i+1:02d}"},'expectedLedger':{'turn':i+2,'lastVerb':verb},'forbiddenProse':['no uncommitted damage','no uncommitted gold','no invented ownership','no outcome guarantee']})
        out['newModules'][mid]={'ledgerFields':fields,'roundResolve':['validate action against committed ledger','validate action cost and legal target','roll or calculate only through CODE','apply statuses and resource deltas','commit ledger atomically','narrate the committed result only'],'wipeCheckpoint':{'wipe':'return to last checkpoint','retain':'personal loot and prior quest completion','clear':'encounter-only state','permadeathV1':False},'weeklyLockout':{'scope':'per-character per-boss','saleBypass':False},'statuses':[{'id':x,'durationTurns':1+(i%3),'numericModifier':(-1 if x in ['rattled','exposed','slowed','spent','marked','wary'] else 1)} for i,x in enumerate(STATUSES)],'verbs':[{'id':v,'display':v.replace('_',' ').title(),'requiresCommit':True} for v in c['verbs']],'chromeTemplates':[{'id':f"{mid}_chrome_{i+1:02d}",'label':x,'template':f"[{x}] {{{{{c['fields'][i%len(c['fields'])][0]}}}}} • turn {{{{turn}}}} • committed"} for i,x in enumerate(['Ledger','Turn','Status','Route','Party','Checkpoint','Reward','Safety'])],'evalProbes':probes}
    return out

def pack_doc(w,data,places):
    kits=data['kits']; npcs=data['npcs']; qs=data['quests']; sp=data['species']; items=data['items']; dungeon=data['dungeons'][0]; bans=make_bans(w)
    pitch=(f"{w['name']} is a WOF text world about {w['concept'].lower()} Players begin with an immediate local problem, choose a visible stake, and work alone or in private co-op with up to five invited friends. The engine commits every ledger change before the narrator describes it, so a useful repair, a careful refusal, or a hard-won route has a traceable result. The world includes its Theme Kit with purchase, keeps gold separate from cosmetic tokens, and refuses gacha, paid power, lockout skips, or outcome sales. Its voice is specific to its places and people; it does not pretend to be a live public MMO.")
    chrome=[f"[{label}] {w['name']} • {{{{{key}}}}} • committed" for label,key in zip(['Ledger','Route','Work','Talk','Kit','Pack','Rest','Safety'],['turn','placeId','lastAction','npcId','kitId','partySize','checkpoint','ageGate'])]
    opening=[]
    for i,k in enumerate(kits):
        opening.append((k['publicName'],f"At {places[i%2]['publicName']}, you arrive in {k['starterClothes']} carrying {k['starterMapItem']}. A small obligation is already late.",['Give up one turn to help now.','Spend one starter supply to solve it cleanly.','Risk a polite refusal and ask for context.','Take a marked detour that changes the first reward.'][i],qs[i]['title']))
    npcrows=[]
    for n,t in zip(npcs,data['talkTrees']): npcrows.append((n['id'],n['name'],n['placeId'],n['role'],t['greet'],t['quest_offer'],t['refusal']))
    place_rows=[(p['id'],p['publicName'],p['role'],p['mapScale'],p['dangerTier'],'yes' if p['outdoor'] else 'no',', '.join(p['exits']),p['problem']) for p in places]
    qrows=[(q['id'],q['title'],q['family'],'yes' if q['hidden'] else 'no', '; '.join(o['kind'] for o in q['objectives']),q['rewardGold'],q['rewardXp']) for q in qs]
    contracts=[(f"{w['id']}_contract_{i+1:02d}",f"{w['name']} {['Local Care','Route Check','Craft Session','Helpful Visit','Instance Practice','Festival Preparation','Record Review','Return Shift'][i]}", 'daily' if i<5 else 'weekly', 1 if i<5 else 2, f"{10+i*5} gold; cosmetic-only bonus mark") for i in range(8)]
    return f"""# WOF {w['name']}: Full Start-Depth Pack\n\n> **Release truth.** {w['name']} is designed for **solo** and **private co-op** sessions. It must not be marketed as an MMO before that capability is proven. The shared engine commits dice, HP and ledger changes, catalogues, quest ticks, loot, gold, lockouts, and instance seeds before any language model narration.\n\n## 0. Header\n\n| Field | Specification |\n| --- | --- |\n| worldId | `{w['id']}` |\n| Display name | **{w['name']}** |\n| One-line pitch | {w['concept']} |\n| Maturity | **{w['maturity']}** |\n| rulesModuleId | `{w['module']}` |\n| Theme Kit | **{w['name']} Theme Kit**, included with world entitlement |\n| Genre pattern and fence | {w['pattern'].capitalize()}. {w['fence']} |\n\n{pitch}\n\n### Genre-specific ban-list (50)\n\n{tbl(['#','Prohibited lookalike or imitation'],[(i+1,b) for i,b in enumerate(bans)])}\n\n## 1. Rules in this skin\n\n| Rule | World application |\n| --- | --- |\n| Active ledger fields | {', '.join(k for k,_ in MODULES_NEW.get(w['module'],{}).get('fields',[])) if w['module'] in MODULES_NEW else REUSED.get(w['module'],'shared module reference')} |\n| Wipe and checkpoint | Wipe returns the party to `{dungeon['rooms'][3]['id']}` after it is activated. Personal loot and completed quests remain; encounter-only state resets. No permadeath. |\n| Lockout | Weekly, per-character, per-boss only; no store item bypasses it. |\n| Prose forbidden to invent | Damage, gold, catch/trust changes, {('lap time' if w['module']=='lap_time' else 'score, deed, reputation, part-break, café rating, or ownership')} values; all must be committed in YAML-backed ledger state first. |\n| Party and presence | Friends-first 2–5; no mid-combat fill. Presence supplies only nearbyPlayerCount and kit/race tags, never stranger names. |\n\n### Diegetic chrome templates\n\n{tbl(['#','Copy-paste template'],[(i+1,c) for i,c in enumerate(chrome)])}\n\n## 2. Identity kits\n\n{tbl(['id','Public name','Look','Values','Taboo','Speech tell','Starter clothes / tool / map','Start and first-hour quest','abilityFlag'],[(k['id'],k['publicName'],k['look'],k['values'],k['taboo'],k['speechTell'],f"{k['starterClothes']}; {k['starterTool']}; {k['starterMapItem']}",f"{k['startingPlaceId']}; {k['firstHourQuestId']}",k['abilityFlag']) for k in kits])}\n\n## 3. Map and places — full graph\n\n**Fog policy.** Visited places reveal full text; unvisited places show outline only. Street maps use pins; interior graphs use room-scale floor plans. No huge-distance chrome is shown inside a shop, room, berth, studio, or home. `{places[0]['id']}` is a shared hub rather than a capital analogue; `{places[3]['id']}` is the mid-join; `{places[5]['id']}` is the instance door. {'`brasswake_place_07` and `brasswake_place_08` are sky-isle POIs with packet-skiff airship exits recorded in YAML.' if w['id']=='brasswake' else ''}\n\n{tbl(['id','Public name','Role','Scale','Danger','Outdoor','Exits','Hour-one local problem'],place_rows)}\n\n## 4. Durable NPCs and premade talk trees\n\n{tbl(['id','Name','placeId','Role','Greet','Quest offer','Refusal'],npcrows)}\n\n### Canned hub say and emote lines\n\n{tbl(['#','Canned line'],[(i+1,x) for i,x in enumerate([f"I can point you toward {places[i%8]['publicName']}, if that is useful.",f"{w['name']} feels different when the small work is done.",f"I am here for a quiet task, not a loud argument.",f"That marker belongs at {places[(i+2)%8]['publicName']}.",f"Let’s keep the route clear for whoever comes after.",f"A good note saves a long explanation.",f"I have room for one more careful pair of hands.",f"The local rule is simple; the reason is not.",f"I can wait while you check your ledger.",f"That is kind of you to ask first.",f"We can take the safer path without making a scene.",f"I will remember that help came from this direction."])])}\n\n## 5. Premade choices and first hour\n\n### Opening establishment deck\n\n{tbl(['Kit','Look and origin','Visible stake','First quest'],opening)}\n\nEach hub has ten inventory-aware choice buttons in `WOF_{w['id']}_data.yaml`; the full set contains {len(data['choiceButtons'])} buttons. Their intents are talk, inspect, interact, travel, rest, and craft/activity as appropriate to this skin—never an incoherent combat action.\n\n**Skippable tutorial on alts.** 1) choose a kit; 2) read the local notice; 3) accept or decline a stake; 4) commit one safe action; 5) meet the first durable NPC; 6) collect one useful item; 7) choose a route to mid-join; 8) bind the first checkpoint.\n\n### Retry deck\n\n{tbl(['#','Goal','Tactic','Obstacle','Revelation','Consequence'],[(i+1,f"Resolve {places[i%8]['publicName']}’s small mismatch",['ask','repair','carry','listen','map','prepare','wait','return'][i],['missing tag','closed path','unclear note','late guest','wet weather','busy shift','quiet boundary','wrong room'][i],f"A local need at {places[(i+3)%8]['publicName']} is connected but not catastrophic.",['alternate talk','new route','recorded favor','cosmetic keepsake','slower reward','safer shortcut','solo option','extra context'][i]) for i in range(8)])}\n\n## 6. Quests — code-completeable DAGs\n\n**Campaign spine.** The 25 beats move from identity and profession tasks to a local zone threat, then to `{w['instance']}` and `{w['big']}`. The side branches do not recycle title structure, and every objective uses an engine enum with an ID and count in the YAML sidecar.\n\n{tbl(['id','Title','Family','Hidden','Objective kinds','Gold','XP'],qrows)}\n\n### Three walk-aways that write divergence records\n\n1. Decline the first obligation at `{places[0]['publicName']}`: write `{w['id']}_divergence_01`; a respectful solo route opens.\n2. Leave the mid-join discussion at `{places[3]['publicName']}`: write `{w['id']}_divergence_02`; the next NPC has context but no punishment.\n3. Step away from the instance breadcrumb: write `{w['id']}_divergence_03`; the instance remains available after a local trust task.\n\n## 7. Species, opponents, and collectibles\n\n{tbl(['id','Name','Kind','HP / armor / threat','Code ownership'],[(s['id'],s['publicName'],s['kind'],f"{s['hp']} / {s['armor']} / {s['threat']}",s['ownedStatNote']) for s in sp])}\n\nThese records support different loops: some are opponents, some are activity partners, and some are habitat or customer equivalents. They do not collapse into a single observe-and-log loop.\n\n## 8. Loot and economy\n\n| Economy component | Implementation |\n| --- | --- |\n| Gold wallet | **{w['wallets'][0]}**; earned from numeric quest rewards, capped repeats, vendors, and personal drops. |\n| Cosmetic-token wallet | **{w['wallets'][1]}**; cosmetic presentation only; no conversion from or into power. |\n| Starter and profession templates | {', '.join(i['publicName'] for i in items[:6])}. |\n| Instance and cosmetic templates | {', '.join(i['publicName'] for i in items[6:12])}. |\n| Drop policy | Twelve named personal-loot tables in YAML, each with percentage, min, max, source ID, and no group roll. |\n| Vendor | `{data['vendors'][0]['id']}` at `{places[0]['id']}`; listed prices are numeric. Repair cost per point: {data['vendors'][0]['repairCostPerPoint']}. |\n| Faucets and sinks | Faucet: quest, sale, capped contract, personal loot. Sink: vendors, repair where applicable, cosmetic display, and craft inputs. Repeat gold cap: {data['dailyCaps']['goldFromRepeatables']} per day. |\n\n## 9. Instances\n\n### Five-room private-co-op instance\n\n| Room id | Name | Room-first description rule | Encounter | Checkpoint / boss |\n| --- | --- | --- | --- | --- |\n""" + ''.join(f"| {r['id']} | {r['publicName']} | {r['describeBeforeCreature']} | trash: {', '.join(r['trashSpeciesIds'])}; elite: {r['eliteSpeciesId'] or 'none'} | {'checkpoint' if r['checkpoint'] else ''} {'boss: '+r['bossSpeciesId'] if r['bossSpeciesId'] else ''} |\n" for r in dungeon['rooms']) + f"""\n\n**Six interactable traps, secrets, and locks.** {', '.join(t['publicName']+' (`'+t['id']+'`)' for t in dungeon['traps'])}. Each is an interactable, not unstructured narration.\n\n### Big night\n\n**{w['big']}** is a 2–5 player big night with three phases: (1) preparation and clear cues, (2) shared activity or finale, and (3) a cosmetic-only closing record. It is not a raid unless a later combat-skin capacity approval explicitly changes it.\n\n## 10. Progression\n\n{tbl(['id','Node','Cost','Requires','Effect flags'],[(t['id'],t['publicName'],t['cost'],', '.join(t['requires']) or 'none',', '.join(t['effectFlags'])) for t in data['talents']])}\n\n{tbl(['id','Contract','Cadence','Cap','Reward'],contracts)}\n\n## 11. Housing and objects\n\n{tbl(['id','Display name','Shared verb id','Place'],[(i['id'],i['publicName'],i['verbId'],i['placeId']) for i in data['interactables']])}\n\n**Default interior graph.** `{data['interiors'][0]['id']}` enters from `{data['interiors'][0]['entrancePlaceId']}` and contains {len(data['interiors'][0]['rooms'])} connected rooms: {', '.join(r['publicName'] for r in data['interiors'][0]['rooms'])}. This is text place/prop data, not a 3D asset request.\n\n## 12. Theme Kit\n\n| Component | Direction |\n| --- | --- |\n| Materials / colors | {', '.join(world_words(w)[:4])} materials with restrained local color, legible paper, cloth, metal, stone, water, or wood texture. |\n| Dice material | A small tactile `{w['name']}` pressed-resin die with an engraved route mark; flat UI representation only. |\n| Voice | {w['voice']} |\n| Default fashion | The starter clothes of the selected kit, with no copied costume silhouette. |\n\n**Ambient loop brief (120 words).** Build a one-minute loop from the everyday acoustics of {w['name']}: distant work, a room tone, a gentle rhythm that belongs to {places[0]['publicName']}, and a second layer that makes the route toward {places[5]['publicName']} feel possible without becoming ominous. Use original instruments or foley only, with a soft entry and an unforced end suitable for text reading. Keep the melody spare so TTS remains intelligible. The mix must not quote, imitate, or allude to a recognizable game, television, film, or popular song motif. Offer a lower-sensory variant with reduced transient sounds. No audio file is generated in this pack; this is an acceptance-ready brief for later production.\n\n{tbl(['#','Skinned UI label'],[(i+1,f"{w['name']} {x}") for i,x in enumerate(['Ledger','Route','Work','Talk','Kit','Pack','Rest','Safety','Map','Notice','Favour','Gold','Token','Record','Instance','Checkpoint','Choice','Help','Calendar','Exit'])])}\n\n{tbl(['#','New Game hook'],[(i+1,f"At {places[i%8]['publicName']}, a small promise has your name on it.") for i in range(10)])}\n\n## 13. Failures and defaults\n\n**Clone-risk and avoidance.** The closest risk is {w['pattern']}. The pack avoids it through original hub names, original kit jobs, proprietary-free creature records, a separate local problem structure, and a ban-list that prevents borrowed marks, silhouettes, maps, slogans, creatures, and UI tropes.\n\n**Defaults.** SPEC: the initial sidecar assumes one private session owns one deterministic instance seed and that big-night cosmetic grants are account-entitlement checked. These are product specifications, not a claim of operating capacity. No John’s call is required: unresolved choices use the safe default of a reversible, non-punitive alternate route.\n"""

def art_paragraph(w, asset, subject, place, kit, kid):
    text=f"""Create the {asset} for **{w['name']}** around {subject}. The subject must be visibly rooted in {place} and include the actual {kit} kit: {kit} clothing, one named tool, and a readable piece of the world’s text interface rather than generic fantasy UI. Use the material vocabulary of {', '.join(world_words(w)[:4])}, with original surfaces, weather, and light that express {w['concept'].lower()} Camera framing must reserve a clean phone-safe centre crop at 9:16 while retaining an expandable 16:9 composition. The image must show one local practical stake—an open notice, a marked route, a shared object, or a useful task—not a world-ending battle. It must not include any prohibited silhouette, logo, named lookalike, recognisable costume code, 3D render callout, or unlicensed text. {('Provide a softened Kid variant: remove threat cues, use clear daytime light, and replace tension with a solvable task.' if kid else 'This asset follows the listed maturity gate; if the scene cannot be made appropriate, omit it rather than forcing a misleading rewrite.')} Add accessible alt-text describing subject, place, action, and primary visual hierarchy."""
    return ' '.join(text.split())

def art_doc(w,data,places):
    assets=[]
    def add(fn,typ,subject,place,kit,kid=False): assets.append((fn,typ,art_paragraph(w,typ,subject,place,kit,kid)))
    add(f"wof_{w['id']}_icon.png",'app icon',f"a compressed emblem of {w['hubs'][0]}",places[0]['publicName'],w['kits'][0],True)
    add(f"wof_{w['id']}_keyart_hero.png",'key art hero',f"the first commitment at {places[0]['publicName']}",places[0]['publicName'],w['kits'][0])
    add(f"wof_{w['id']}_keyart_kid.png",'key art Kid/safety variant',f"a safe shared task at {places[1]['publicName']}",places[1]['publicName'],w['kits'][1],True)
    for i in range(8): add(f"wof_{w['id']}_shot_{i+1:02d}.png",'store screenshot shot list',f"UI chrome {['Ledger','Route','Work','Talk','Kit','Pack','Rest','Safety'][i]} during a readable choice",places[i]['publicName'],w['kits'][i%4],w['maturity']!='teen+')
    for i,k in enumerate(w['kits']): add(f"wof_{w['id']}_portrait_{i+1:02d}.png",'kit portrait',f"the actual {k} at work with their taboo implied by a careful gesture",places[i]['publicName'],k,w['maturity']=='all-ages')
    for i,which in enumerate(['hub establishing shot','wild establishing shot','instance-door establishing shot','housing/interior establishing shot']): add(f"wof_{w['id']}_place_{i+1:02d}.png",which,f"a named {which}",places[[0,6,5,7][i]]['publicName'],w['kits'][i],w['maturity']=='all-ages')
    for i,which in enumerate(['opening still','first-clear still','first-down still','ending still']): add(f"wof_{w['id']}_still_{i+1:02d}.png",which,f"a memorable {which} from the local campaign",places[[0,3,5,7][i]]['publicName'],w['kits'][i],w['maturity']!='teen+')
    lines=[f"# WOF {w['name']}: Art and Audio Briefs\n","> Every visual brief below is at least 80 words and is a later-production direction, not a binary asset, mesh, navmesh, or collision request.\n"]
    for fn,typ,p in assets: lines += [f"## `{fn}` — {typ}\n",p+'\n']
    lines += [f"## `wof_{w['id']}_ambient_loop.ogg` — ambient loop\n",art_paragraph(w,'ambient-loop direction',f"a one-minute original sound bed made from {w['hubs'][0]} and {w['hubs'][5]}",places[0]['publicName'],w['kits'][0],w['maturity']=='all-ages')+'\n']
    for cue in ['hit','wipe','mail','level','vendor','instance_enter','festival','death']:
        lines += [f"### `wof_{w['id']}_{cue}.ogg`\n",f"Create one short original {cue.replace('_',' ')} cue for {w['name']} using local material sounds, a clear non-startling transient, and no recognizable licensed melody; provide a reduced-sensory alternative where the cue would otherwise spike sharply.\n"]
    return '\n'.join(lines), assets

def press_doc(w,data,places):
    q=data['quests'][0]; kit=data['kits'][0]; bans=make_bans(w)
    clicks=[]
    actions=['open store identity','select age lane','start kit','read opening stake','open Ledger','travel route','meet NPC','accept quest','complete objective','open vendor','check gold wallet','check cosmetic wallet','apply Theme Kit','enter instance door','read room-first text','complete trash step','activate checkpoint','wipe safely','claim personal loot','run a talent node','open home interior','run a daily contract','open big-night record','use report/mute/block','trigger world kill switch']
    for i,a in enumerate(actions): clicks.append((f"{w['id']}_click_{i+1:02d}",a,places[i%8]['id'],f"Expected: {a} completes without a public-MMO claim, power sale, or uncommitted ledger prose."))
    blurb=(f"{w['name']} is a WOF text world about {w['concept'].lower()} It begins at {places[0]['publicName']} with {q['title']}, a small commitment that makes the local texture immediately useful. Choose one of four distinct kits—including the {kit['publicName']}—then follow clear, committed choices through a private solo or 2–5 player co-op session. The named five-room instance, {w['instance']}, uses room-first description and personal loot; the closing {w['big']} gives friends a cosmetic-focused big night rather than a scaled raid claim. A complete {w['name']} Theme Kit is included with the world. Gold, {w['wallets'][0]}, and cosmetic tokens, {w['wallets'][1]}, remain separate. No gacha, outcome sale, lockout skip, or paid power item is offered. It is not described as an MMO until that capability is proven.")
    return f"""# WOF {w['name']}: Bespoke Press Bill\n\n## Store identity\n\n**One-line pitch.** {w['concept']}\n\n{w['name']} begins at **{places[0]['publicName']}**, where **{q['title']}** asks the player to make a practical choice before anything grand occurs. The **{kit['publicName']}** kit sees that problem from a specific working angle, while the route toward **{w['instance']}** introduces a private 2–5 session that is clear about its stakes and its limits. The store page sells a buy-and-own text world for solo/private co-op, not an MMO. Its included **{w['name']} Theme Kit** changes presentation without changing outcomes. Gold is **{w['wallets'][0]}**; cosmetic tokens are **{w['wallets'][1]}**. Neither currency buys power, a better roll, a catch, a clear, or a lockout bypass.\n\n| Field | Release specification |\n| --- | --- |\n| Maturity | {w['maturity']} |\n| Content descriptor | Local stakes, clear safety controls, and world-specific non-graphic tension where applicable. |\n| Included | World entitlement, all authored text data, and Theme Kit. |\n| DLC boundary | Future cosmetic plates only; no content advantage. |\n| Demand row | {w['pattern']} serves the original setting and social/private-co-op demand lane. |\n\n## Code and content remaining\n\n| Item | Status | World-specific requirement |\n| --- | --- | --- |\n| Rule integration | CODE | `{w['module']}` ledger and `{data['evalProbes'][0]['id']}` through `{data['evalProbes'][-1]['id']}`. |\n| Data load | SPEC / CODE | `{w['id']}_places`, kits, NPC trees, quest DAG, drops, vendor, dungeon, interior, talents, and Theme Kit. |\n| First hour | SPEC | {q['title']} at `{places[0]['id']}`, then the mid-join `{places[3]['id']}`. |\n| Instance | SPEC / CODE | `{w['instance']}` through `{places[5]['id']}`. |\n| Big night | SPEC / CODE | `{w['big']}`, 2–5 players, three phases, cosmetic-only record. |\n| Kill switches | CODE | disable `{w['id']}` store listing, starts, instance, big night, Theme Kit apply, or canned talk without affecting other worlds. |\n\n## Legal and trust\n\n{w['fence']} Canned hub lines are authored and not stranger LLM chat. Report, mute, and block are required support flows. Hashed telemetry only; TTS reads chrome and prose; font scaling and non-colour danger indicators are mandatory. Kid Mode, when eligible, limits play to ten text turns per day and disables public DM, trade, and voice.\n\n## Twenty-five click tests\n\n{tbl(['id','Action','Actual placeId','Expected'],clicks)}\n\n## CI ban strings\n\n{tbl(['#','Must reject'],[(i+1,b) for i,b in enumerate(bans[:15])])}\n\n## SPEC LLM budget\n\n| Measure | SPEC |\n| --- | --- |\n| Visible prose per committed turn | 700 target / 1,200 hard ceiling tokens |\n| 95th-percentile post-commit narration | under 3.0 seconds, measured before release claim |\n| Retained narrative context | 18,000 tokens, refreshed from committed ledger events only |\n| Safety sample | 100% store and key-art prompts; 20% canned talk per release candidate |\n\n## Press blurb\n\n{blurb}\n\n## FAQ\n\n| Question | Answer |\n| --- | --- |\n| Is {w['name']} an MMO? | No. It is described as solo/private co-op until multiplayer is proven. |\n| What comes with the purchase? | The world and its complete Theme Kit. |\n| Can I buy a better outcome? | No; outcome sales, power, clears, lockout skips, catch changes, gacha, and loot boxes are prohibited. |\n| What happens after a wipe? | Return to the named checkpoint; retain personal loot and completed progress. |\n| How is social play kept safe? | Friends-first private co-op, canned hub lines, and report/mute/block; no global chat or public DMs. |\n\n## Not ready / still CODE\n\nEntitlement restoration, exact ledger calls, deterministic instance seeding, feature flags, kill-switch monitoring, report pipeline, accessibility acceptance, device performance test, and final legal/ratings review remain CODE or approval work. This bill does not represent them as already live.\n"""

# Generate all primary world artifacts.
art_index=[]; eval_rows=[]; counts=[]
for w in WORLDS:
    data,places=make_world_data(w)
    write(f"WOF_{w['id']}_data.yaml",yaml.safe_dump(data,sort_keys=False,allow_unicode=True,width=120))
    pack=pack_doc(w,data,places); write(f"WOF_{w['id']}_Pack.md",pack)
    press=press_doc(w,data,places); write(f"WOF_{w['id']}_PressBill.md",press)
    art,assets=art_doc(w,data,places); write(f"WOF_{w['id']}_ArtBriefs.md",art)
    for fn,typ,_ in assets: art_index.append((fn,w['id'],typ))
    art_index.append((f"wof_{w['id']}_ambient_loop.ogg",w['id'],'ambient loop'))
    art_index += [(f"wof_{w['id']}_{cue}.ogg",w['id'],'sfx') for cue in ['hit','wipe','mail','level','vendor','instance_enter','festival','death']]
    for e in data['evalProbes']: eval_rows.append((w['id'],e['id'],json.dumps(e['given'],sort_keys=True),json.dumps(e['action'],sort_keys=True),json.dumps(e['expectedLedger'],sort_keys=True),'; '.join(e['forbiddenProse'])))
    counts.append((w['id'],len(data['places']),len(data['npcs']),len(data['quests']),len(data['species']),len(data['items']),len(data['interactables']),len(data['choiceButtons'])))

write('WOF_Rules_Modules_NEW.yaml',yaml.safe_dump(module_yaml(),sort_keys=False,allow_unicode=True,width=120))
write('WOF_Art_Audio_MASTER_INDEX.md','# WOF Art and Audio Master Index\n\n'+tbl(['Filename','worldId','Type'],art_index)+f"\n\n**Total indexed briefs/cues:** {len(art_index)}.\n")
write('WOF_Eval_Probe_Book.md','# WOF Eval Probe Book\n\n'+tbl(['worldId','probeId','given','action','expectedLedger','forbiddenProse'],eval_rows)+f"\n\n**Total probes:** {len(eval_rows)}.\n")

# Homestead deed table and shared verb catalog.
homestead=next(w for w in WORLDS if w['id']=='homestead_ring')
